+/** Reserve an ID without making it observable to queries or world.entities. */
+function reserve(world: World): Entity {
+    const index = world[$internal].entityIndex;
+    const entity = packEntity(index.worldId, 0, index.maxId++);
+    index.sparse[getEntityId(entity)] = index.dense.length;
+    index.dense.push(entity);
+    return entity;
+}
+
+function queue(world: World, command: DeferredCommand) {
+    const commands = current(world);
+    // An updated value replaces the earlier queued add, provided the pair has not
+    // been removed in between. This keeps command ordering while giving set-like
+    // values their expected last-write-wins behaviour.
+    if (command.type === 'add') {
+        for (const config of command.traits) {
+            if (!Array.isArray(config) && !isRelationPair(config)) continue;
+            const trait = traitOf(config);
+            for (let i = commands.length - 1; i >= 0; i--) {
+                const previous = commands[i];
+                if (previous.entity !== command.entity) continue;
+                if (previous.type === 'remove' && previous.traits.some((item) => traitOf(item) === trait)) break;
+                if (previous.type === 'add') {
+                    const index = previous.traits.findIndex((item) => traitOf(item) === trait);
+                    if (index !== -1) previous.traits[index] = config;
+                    else previous.traits.push(config);
+                    break;
+                }
+            }
+        }
+    }
+    commands.push(command);
+}
+
+export function createDeferred(world: World): DeferredCommandBuffer {
+    return {
+        spawn(...traits) {
+            const entity = reserve(world);
+            queue(world, { type: 'spawn', entity, traits });
+            return entity;
+        },
+        destroy(entity) { queue(world, { type: 'destroy', entity }); },
+        add(entity, ...traits) { queue(world, { type: 'add', entity, traits }); },
+        remove(entity, ...traits) { queue(world, { type: 'remove', entity, traits }); },
+        addExclusive(entity, ...pairs) { queue(world, { type: 'addExclusive', entity, pairs }); },
+        flush() { flushDeferred(world, current(world)); },
+    };
+}
