+export function beginDeferredScope(world: World) { world[$internal].deferred.scopes.push([]); }
+export function endDeferredScope(world: World) {
+    const commands = world[$internal].deferred.scopes.pop()!;
+    flushDeferred(world, commands);
+}
+
+export function hasPendingDeferred(world: World, entity: Entity) {
+    return [world[$internal].deferred.root, ...world[$internal].deferred.scopes].some((commands) =>
+        commands.some((command) => command.entity === entity)
+    );
+}
+
+export function flushDeferredForEntity(world: World, entity: Entity) {
+    if (!hasPendingDeferred(world, entity)) return;
+    // A mutation must observe every earlier command, including commands targeting
+    // other entities, so flush buffers in their chronological nesting order.
+    flushDeferred(world, world[$internal].deferred.root);
+    for (const commands of world[$internal].deferred.scopes) flushDeferred(world, commands);
