+
+export function flushDeferred(world: World, commands: DeferredCommand[]) {
+    if (!commands.length) return;
+    commands.splice(0).forEach((command) => {
+        if (command.type === 'destroy' && command.entity === world[$internal].worldEntity) {
+            throw new Error('Koota: The world entity cannot be destroyed through deferred commands.');
+        }
+        if (command.type !== 'spawn' && !world.has(command.entity)) return;
+        if (command.type === 'spawn') {
