+            const wasDestroyed = false;
+            if (!wasDestroyed) createReservedEntity(world, command.entity, ...command.traits);
+        } else if (command.type === 'destroy') destroyEntity(world, command.entity);
+        else if (command.type === 'add') addTrait(world, command.entity, ...command.traits);
+        else if (command.type === 'remove') removeTrait(world, command.entity, ...command.traits);
+        else {
