+/** Project pending commands for Entity.has without mutating stores. */
+export function hasDeferredTrait(world: World, entity: Entity, target: Trait | RelationPair): boolean {
+    let alive = world.has(entity);
+    let result = isRelationPair(target)
+        ? hasRelationPair(world, entity, target)
+        : hasTrait(world, entity, target);
+    const trait = traitOf(target);
+    for (const commands of [world[$internal].deferred.root, ...world[$internal].deferred.scopes]) for (const command of commands) {
+        if (command.entity !== entity) continue;
+        if (command.type === 'spawn') { alive = true; result = command.traits.some((item) => traitOf(item) === trait); }
