+        if (!alive) continue;
+        if (command.type === 'add' && command.traits.some((item) => traitOf(item) === trait)) result = true;
+        if (command.type === 'remove' && command.traits.some((item) => traitOf(item) === trait)) result = false;
+        if (command.type === 'addExclusive' && isRelationPair(target) && command.pairs.some((pair) => pair[$internal].relation === target[$internal].relation)) {
+            result = command.pairs.some((pair) => pair[$internal].target === target[$internal].target);
+        }
+    }
+    return alive && result;
+}
